package ca.yorku.eecs3311.coursepilot.application.service;
import ca.yorku.eecs3311.coursepilot.application.ai.*; import ca.yorku.eecs3311.coursepilot.application.dto.*; import ca.yorku.eecs3311.coursepilot.domain.model.*; import ca.yorku.eecs3311.coursepilot.domain.repository.*; import com.fasterxml.jackson.databind.ObjectMapper; import org.springframework.beans.factory.annotation.Value; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.text.Normalizer; import java.util.*;
@Service public class QuizGenerationService {private final CourseMaterialService materials;private final LlmClient llm;private final PromptBuilder prompts;private final StructuredResponseParser parser;private final GroundingContextBuilder builder;private final QuizRepository quizzes;private final int maxContext,maxCount;
 public QuizGenerationService(CourseMaterialService m,LlmClient l,PromptBuilder p,StructuredResponseParser s,GroundingContextBuilder b,QuizRepository q,@Value("${coursepilot.quiz.max-context-characters:12000}")int mc,@Value("${coursepilot.quiz.max-count:20}")int mx){materials=m;llm=l;prompts=p;parser=s;builder=b;quizzes=q;maxContext=mc;maxCount=mx;}
@Transactional public QuizGenerationResult generate(Long courseId,Long documentId,Integer count,Set<String> requestedTypes){int n=count==null?10:count;if(n<1||n>maxCount)throw new IllegalArgumentException("Quiz count must be between 1 and "+maxCount+".");Set<String> types=requestedTypes==null||requestedTypes.isEmpty()?Set.of("MULTIPLE_CHOICE","TRUE_FALSE","SHORT_ANSWER"):requestedTypes.stream().map(this::normalizeType).collect(java.util.stream.Collectors.toCollection(LinkedHashSet::new));for(String x:types)try{QuizQuestionType.valueOf(x);}catch(Exception e){throw new IllegalArgumentException("Unsupported quiz question type: "+x);}DocumentResponse doc=materials.getDocument(courseId,documentId);if(!"READY".equals(doc.processingStatus()))throw new InsightGenerationException("This material is not ready for quiz generation.");List<DocumentChunk> chunks=materials.listChunks(courseId,documentId);List<SearchResult> results=chunks.stream().map(c->new SearchResult(c.getDocument().getId(),c.getId(),c.getDocument().getOriginalFilename(),c.getChunkIndex(),c.getContent(),1d,c.getStartPage(),c.getEndPage(),List.of())).toList();var context=builder.build(results,maxContext);if(!llm.checkAvailability().isAvailable())throw new InsightGenerationException("AI quiz generation is currently unavailable.");QuizGenerationLlmResponse generated;try{generated=parse(n,String.join(",",types),doc.originalFilename(),context.text());}catch(RuntimeException e){try{generated=parse(n,String.join(",",types),doc.originalFilename(),builder.build(results,Math.min(maxContext,4000)).text());}catch(RuntimeException retry){throw new InsightGenerationException("The AI quiz could not be processed safely.",retry);}}Map<String,GroundedSource> sourceMap=new LinkedHashMap<>();context.sources().forEach(s->sourceMap.put(s.sourceId(),s));Set<String> seen=new HashSet<>();Quiz quiz=new Quiz(chunks.getFirst().getDocument().getCourse(),doc.originalFilename()+" quiz");int saved=0;ObjectMapper mapper=new ObjectMapper();for(var q:generated.questions()){if(saved>=n||q.prompt()==null||q.prompt().isBlank()||!seen.add(normalize(q.prompt())))continue;QuizQuestionType type;try{type=QuizQuestionType.valueOf(normalizeType(q.type()));}catch(Exception e){continue;}if(!types.contains(type.name())||q.sourceIds().isEmpty()||q.sourceIds().stream().anyMatch(id->id==null||!sourceMap.containsKey(id.trim().toUpperCase(Locale.ROOT))))continue;List<String> options=q.options().stream().filter(Objects::nonNull).map(String::trim).filter(x->!x.isBlank()).distinct().toList();String correctAnswer=normalizeAnswer(q.correctAnswer(),options);if(type==QuizQuestionType.MULTIPLE_CHOICE&&(options.size()<2||correctAnswer==null||!options.contains(correctAnswer)))continue;if(type==QuizQuestionType.TRUE_FALSE&&!("true".equalsIgnoreCase(q.correctAnswer())||"false".equalsIgnoreCase(q.correctAnswer())))continue;if(type==QuizQuestionType.SHORT_ANSWER&&(q.referenceAnswer()==null||q.referenceAnswer().isBlank()))continue;String json;try{json=mapper.writeValueAsString(options);}catch(Exception e){continue;}QuizQuestion question=new QuizQuestion(quiz,type,q.prompt().trim(),json,correctAnswer,q.referenceAnswer());for(String id:q.sourceIds()){GroundedSource s=sourceMap.get(id.trim().toUpperCase(Locale.ROOT));DocumentChunk c=chunks.stream().filter(x->x.getId().equals(s.chunkId())).findFirst().orElse(null);if(c!=null)question.addSource(new QuizSource(question,c.getDocument(),c.getId(),c.getChunkIndex(),c.getStartPage(),c.getEndPage()));}quiz.addQuestion(question);saved++;}if(saved==0)throw new InsightGenerationException("No valid quiz questions were returned by the AI.");quizzes.save(quiz);return new QuizGenerationResult(n,saved,QuizResponseDto.from(quiz));}
 private QuizGenerationLlmResponse parse(int count,String types,String label,String context){return parser.parse(llm.generate(prompts.buildQuizGenerationPrompt(count,types,label,context)).content(),QuizGenerationLlmResponse.class);}private String normalizeAnswer(String answer,List<String> options){if(answer==null)return null;String value=answer.trim();if(value.length()==1&&value.charAt(0)>='A'&&value.charAt(0)<='Z'){int index=value.charAt(0)-'A';if(index<options.size())return options.get(index);}return value;}private String normalize(String s){return Normalizer.normalize(s,Normalizer.Form.NFKC).trim().replaceAll("\\s+"," ").toLowerCase(Locale.ROOT);}private String normalizeType(String s){return s==null?"":s.trim().toUpperCase(Locale.ROOT).replace('-', '_').replace(' ', '_');}}
